draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // draw arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  // draw legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 20 * Math.cos(t), H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 20 * Math.cos(t), H/2 + 80);
  ctx.stroke();

  // draw choice paths
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 50 + 30 * Math.sin(2 * t), H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 50 + 30 * Math.sin(2 * t), H/2 + 150);
  ctx.stroke();

  ctx.restore();
}
